CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('student','admin')), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS groups (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, created_by INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS group_members (group_id INT REFERENCES groups(id) ON DELETE CASCADE, student_id INT REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(group_id,student_id), UNIQUE(student_id));
CREATE TABLE IF NOT EXISTS assignments (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT, due_date TIMESTAMPTZ NOT NULL, onedrive_link TEXT NOT NULL, created_by INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_all BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS assignment_groups (assignment_id INT REFERENCES assignments(id) ON DELETE CASCADE, group_id INT REFERENCES groups(id) ON DELETE CASCADE, PRIMARY KEY(assignment_id,group_id));
CREATE TABLE IF NOT EXISTS submissions (id SERIAL PRIMARY KEY, assignment_id INT REFERENCES assignments(id) ON DELETE CASCADE, group_id INT REFERENCES groups(id) ON DELETE CASCADE, student_id INT REFERENCES users(id) ON DELETE CASCADE, confirmed BOOLEAN DEFAULT FALSE, confirmed_at TIMESTAMPTZ, UNIQUE(assignment_id,student_id));
